def compute(vars):
    bookings_2018 = vars["v1"]
    bookings_2019 = vars["v2"]
    average_total_bookings = (bookings_2018 + bookings_2019) / 2

    return {
        "value": average_total_bookings,
        "trace": {
            "bookings_2018": bookings_2018,
            "bookings_2019": bookings_2019,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
